mapper.select:
SELECT
i.*,
p.prod_name,
c.category_level1,
c.category_level2,
c.category_level3
FROM inventory i
JOIN product p ON i.prod_id = p.prod_id
JOIN category c ON p.prod_categoryid = c.prod_categoryid
WHERE 1=1

    AND i.client_id = #{clientId}


    AND p.prod_name LIKE CONCAT('%', #{prodName}, '%')


    AND i.ware_id = #{wareId}


    AND c.category_level1 = #{categoryLevel1}


    AND c.category_level2 = #{categoryLevel2}


    AND c.category_level3 = #{categoryLevel3}



        ORDER BY i.quantity ASC


        ORDER BY i.quantity DESC


        ORDER BY p.prod_name ASC


LIMIT #{skip}, #{amount}
